    { id: 'wright', data: [1903, 12], categoria: 'tecnologia', titulo: 'O primeiro voo motorizado', fato: 'Em 17 de dezembro de 1903, em Kitty Hawk, na Carolina do Norte, os irmãos Wright fizeram o primeiro voo controlado de um avião a motor: 12 segundos no ar.', fonte: 'Smithsonian National Air and Space Museum.' },
    { id: 'sf_terremoto', data: [1906, 4], categoria: 'desastre', titulo: 'O terremoto de São Francisco', fato: 'Em 18 de abril de 1906, um terremoto e os incêndios que vieram depois destruíram boa parte de São Francisco; mais de 3 mil pessoas morreram e metade da cidade ficou sem casa.', divisoes: ['CA'], fonte: 'U.S. Geological Survey.' },
    { id: 'modelo_t', data: [1908, 10], categoria: 'economia', titulo: 'O carro para todo mundo', fato: 'Em outubro de 1908 saiu da fábrica o primeiro Ford Modelo T; com a linha de montagem (1913), o preço caiu ano a ano e o automóvel deixou de ser só dos ricos.', peso: 'cotidiano', fonte: 'The Henry Ford (museu); Smithsonian.' },
    { id: 'imposto_renda', data: [1913, 2], categoria: 'economia', titulo: 'A 16ª Emenda: o imposto de renda federal', fato: 'Em fevereiro de 1913, a 16ª Emenda à Constituição autorizou o imposto de renda federal; no começo, ele atingia só as rendas mais altas.', peso: 'cotidiano', idadeMin: 18, fonte: 'National Archives (16ª Emenda, ratificada em 03/02/1913).' },
    { id: 'guerra_1917', data: [1917, 4], categoria: 'guerra', titulo: 'Os Estados Unidos entram na Primeira Guerra', fato: 'Em 6 de abril de 1917, o Congresso declarou guerra à Alemanha. A convocação (Selective Service Act, maio de 1917) chamou milhões de homens; mais de 116 mil soldados americanos morreram.', peso: 'biografia', fonte: 'National Archives; Department of Veterans Affairs (America\'s Wars).' },
    { id: 'gripe_1918', data: [1918, 10], categoria: 'saude', titulo: 'A gripe de 1918', fato: 'No outono de 1918, a pandemia de gripe chegou ao auge: escolas, igrejas e teatros fecharam, e máscaras de gaze viraram obrigatórias em várias cidades. No país, morreram cerca de 675 mil pessoas.', peso: 'biografia', idadeMin: 4, especial: { tipo: 'pandemia', risco: 0.25, texto: 'Quase toda família teve alguém de cama.' }, fonte: 'Centers for Disease Control and Prevention (CDC), "1918 Pandemic".' },
    { id: 'lei_seca', data: [1920, 1], categoria: 'sociedade', titulo: 'A Lei Seca entra em vigor', fato: 'Em 17 de janeiro de 1920, a 18ª Emenda proibiu fabricar, vender e transportar bebida alcoólica. Os bares viraram speakeasies escondidos, e o contrabando fez a fortuna do crime organizado.', fonte: 'National Archives (18ª Emenda; Lei Volstead, 1919).' },
    { id: 'voto_feminino', data: [1920, 8], categoria: 'direitos', titulo: 'A 19ª Emenda: as mulheres votam', fato: 'Em 18 de agosto de 1920, a 19ª Emenda foi ratificada: o direito de voto não podia mais ser negado por causa do sexo. Em novembro, as mulheres votaram em todo o país.', peso: 'biografia', pessoal: { mulher: 'Você passou a votar — o que a sua mãe, em boa parte dos estados, nunca tinha podido fazer.' }, fonte: 'National Archives (19ª Emenda).' },
    { id: 'cidadania_indigena', data: [1924, 6], categoria: 'direitos', titulo: 'A Lei da Cidadania Indígena', fato: 'Em junho de 1924, o Indian Citizenship Act deu cidadania a todos os indígenas nascidos no país — embora vários estados ainda tenham negado o voto a eles por décadas.', peso: 'cotidiano', idadeMin: 14, fonte: 'Library of Congress; National Archives.' },
    { id: 'cinema_falado', data: [1927, 10], categoria: 'cultura', titulo: 'O cinema passa a falar', fato: 'Em outubro de 1927 estreou o primeiro longa-metragem com falas e canções sincronizadas. Em três anos, quase todo filme era falado — e os músicos que tocavam nas salas perderam o emprego.', peso: 'cotidiano', fonte: 'Library of Congress (National Film Registry).' },
    { id: 'crash_1929', data: [1929, 10], categoria: 'economia', titulo: 'A quebra da Bolsa de Nova York', fato: 'Em 24 e 29 de outubro de 1929, a Bolsa de Nova York desabou. Veio a Grande Depressão: bancos quebraram aos milhares, e em 1933 um em cada quatro trabalhadores estava sem emprego.', peso: 'biografia', mods: { demissao: 1.6, contratacao: -0.12, clientela: -10 }, dura: 3, efeito: 'Nos anos seguintes, o emprego sumiu e quem tinha negócio viu a freguesia minguar.', pessoal: { trabalho: 'No trabalho, cada mês alguém era dispensado; segurar o emprego virou a prioridade da casa.', semTrabalho: 'Procurar trabalho virou fila: na porta das fábricas, centenas de homens para uma vaga.' }, fonte: 'Federal Reserve History, "Stock Market Crash of 1929"; Bureau of Labor Statistics.' },
    { id: 'bancos_1933', data: [1933, 3], categoria: 'economia', titulo: 'O feriado bancário', fato: 'Em março de 1933, logo depois da posse, Franklin Roosevelt fechou todos os bancos do país por uma semana; só reabriram os que estavam saudáveis. Em junho, a lei bancária criou o seguro dos depósitos (FDIC).', peso: 'biografia', idadeMin: 12, fonte: 'Federal Reserve History, "Banking Act of 1933 (Glass-Steagall)"; FDIC.' },
    { id: 'fim_lei_seca', data: [1933, 12], categoria: 'sociedade', titulo: 'O fim da Lei Seca', fato: 'Em 5 de dezembro de 1933, a 21ª Emenda revogou a Lei Seca: a bebida voltou a ser legal, regulada por cada estado.', peso: 'cotidiano', fonte: 'National Archives (21ª Emenda).' },
    { id: 'social_security', data: [1935, 8], categoria: 'direitos', titulo: 'A Lei da Seguridade Social', fato: 'Em agosto de 1935, o Social Security Act criou a aposentadoria pública federal e o seguro-desemprego. Os primeiros benefícios mensais saíram em 1940 — mas trabalhadores rurais e domésticos, muitos deles negros, ficaram de fora até os anos 1950.', peso: 'biografia', idadeMin: 14, fonte: 'Social Security Administration (Historical Background).' },
    { id: 'flsa', data: [1938, 10], categoria: 'direitos', titulo: 'O salário mínimo e a semana de 40 horas', fato: 'Em outubro de 1938 entrou em vigor a Fair Labor Standards Act: salário mínimo federal de 25 centavos por hora, hora extra acima de 44 (depois 40) horas por semana e limites ao trabalho infantil.', peso: 'cotidiano', idadeMin: 12, fonte: 'U.S. Department of Labor.' },
    { id: 'pearl_harbor', data: [1941, 12], categoria: 'guerra', titulo: 'O ataque a Pearl Harbor', fato: 'Em 7 de dezembro de 1941, a aviação japonesa atacou a base naval de Pearl Harbor, no Havaí; no dia seguinte, os Estados Unidos entraram na Segunda Guerra. Mais de 16 milhões de americanos vestiram farda até 1945.', peso: 'biografia', idadeMin: 5, fonte: 'National WWII Museum; National Archives.' },
    { id: 'internacao_nipo', data: [1942, 2], categoria: 'direitos', titulo: 'A internação dos nipo-americanos', fato: 'Em fevereiro de 1942, a Ordem Executiva 9066 levou cerca de 120 mil pessoas de origem japonesa — dois terços delas cidadãs americanas — da costa oeste para campos de internação. O governo pediu desculpas formais em 1988.', peso: 'cotidiano', idadeMin: 10, fonte: 'National Archives (Ordem Executiva 9066); Civil Liberties Act de 1988.' },
    { id: 'gi_bill', data: [1944, 6], categoria: 'sociedade', titulo: 'A lei dos veteranos (GI Bill)', fato: 'Em junho de 1944, a GI Bill garantiu aos que voltavam da guerra faculdade paga, seguro-desemprego e empréstimo para a casa própria: milhões de famílias chegaram à classe média e aos subúrbios — com bem menos acesso para os veteranos negros.', peso: 'cotidiano', idadeMin: 14, fonte: 'Department of Veterans Affairs; National Archives.' },
    { id: 'fim_guerra_45', data: [1945, 8], categoria: 'guerra', titulo: 'O fim da Segunda Guerra', fato: 'Em agosto de 1945, depois das bombas atômicas sobre Hiroshima e Nagasaki, o Japão se rendeu. Nas ruas, festa; em muitas casas, a estrela dourada na janela lembrava quem não voltou.', peso: 'biografia', fonte: 'National WWII Museum.' },
    { id: 'robinson', data: [1947, 4], categoria: 'esporte', titulo: 'Jackie Robinson nas grandes ligas', fato: 'Em 15 de abril de 1947, Jackie Robinson entrou em campo pelo Brooklyn Dodgers e quebrou a barreira racial do beisebol das grandes ligas.', peso: 'cotidiano', fonte: 'National Baseball Hall of Fame; Library of Congress.' },
    { id: 'forcas_integradas', data: [1948, 7], categoria: 'direitos', titulo: 'O fim da segregação nas Forças Armadas', fato: 'Em julho de 1948, a Ordem Executiva 9981 determinou igualdade de tratamento nas Forças Armadas, sem distinção de raça.', peso: 'cotidiano', idadeMin: 14, fonte: 'Harry S. Truman Library; National Archives.' },
    { id: 'coreia', data: [1950, 6], categoria: 'guerra', titulo: 'A Guerra da Coreia', fato: 'Em junho de 1950, tropas americanas foram mandadas à Coreia. A convocação voltou a chamar os jovens; até o armistício de 1953, mais de 36 mil americanos morreram.', peso: 'biografia', fonte: 'Department of Veterans Affairs; Korean War Veterans Memorial.' },
    { id: 'brown', data: [1954, 5], categoria: 'direitos', titulo: 'A Suprema Corte proíbe a escola segregada', fato: 'Em 17 de maio de 1954, no caso Brown v. Board of Education, a Suprema Corte decidiu que escolas separadas por raça eram inconstitucionais. Muitos estados do Sul resistiram por mais de uma década.', peso: 'biografia', pessoal: { crianca: 'Na escola, os adultos falavam da decisão em voz baixa.' }, fonte: 'National Archives; Supreme Court of the United States, 347 U.S. 483.' },
    { id: 'montgomery', data: [1955, 12], categoria: 'direitos', titulo: 'O boicote aos ônibus de Montgomery', fato: 'Em dezembro de 1955, Rosa Parks foi presa no Alabama por não ceder o lugar no ônibus a um homem branco; o boicote que se seguiu durou 381 dias e projetou Martin Luther King Jr.', peso: 'cotidiano', idadeMin: 12, fonte: 'National Archives; The King Center.' },
    { id: 'interestaduais', data: [1956, 6], categoria: 'economia', titulo: 'As rodovias interestaduais', fato: 'Em junho de 1956, a Federal-Aid Highway Act começou a construir 66 mil quilômetros de rodovias: o carro, o caminhão e o subúrbio viraram o jeito americano de viver.', peso: 'cotidiano', fonte: 'U.S. Department of Transportation, Federal Highway Administration.' },
    { id: 'sputnik', data: [1957, 10], categoria: 'tecnologia', titulo: 'O satélite soviético e a corrida espacial', fato: 'Em outubro de 1957, a União Soviética pôs o primeiro satélite em órbita. O susto mudou a escola americana: mais ciência, mais matemática e, em 1958, a NASA.', peso: 'cotidiano', fonte: 'NASA History Office.' },
    { id: 'pilula', data: [1960, 5], categoria: 'saude', titulo: 'A pílula anticoncepcional', fato: 'Em maio de 1960, a FDA aprovou a primeira pílula anticoncepcional; em 1965, a Suprema Corte garantiu aos casais o direito de usá-la.', peso: 'cotidiano', idadeMin: 16, fonte: 'U.S. Food and Drug Administration; Griswold v. Connecticut, 381 U.S. 479 (1965).' },
    { id: 'misseis_cuba', data: [1962, 10], categoria: 'guerra', titulo: 'A crise dos mísseis', fato: 'Em outubro de 1962, mísseis soviéticos em Cuba levaram o mundo à beira de uma guerra nuclear por treze dias. Nas escolas, as crianças treinavam se esconder embaixo da carteira.', peso: 'cotidiano', fonte: 'John F. Kennedy Presidential Library.' },
    { id: 'kennedy', data: [1963, 11], categoria: 'politica', titulo: 'O assassinato de Kennedy', fato: 'Em 22 de novembro de 1963, o presidente John F. Kennedy foi morto a tiros em Dallas. Quem viveu aquele dia lembra onde estava quando ouviu a notícia.', peso: 'biografia', fonte: 'John F. Kennedy Presidential Library; National Archives (Comissão Warren).' },
    { id: 'direitos_civis', data: [1964, 7], categoria: 'direitos', titulo: 'A Lei dos Direitos Civis', fato: 'Em 2 de julho de 1964, a Civil Rights Act proibiu a segregação em lugares públicos e a discriminação no emprego por raça, cor, religião, sexo ou origem.', peso: 'biografia', fonte: 'National Archives; U.S. Equal Employment Opportunity Commission.' },
    { id: 'voto_1965', data: [1965, 8], categoria: 'direitos', titulo: 'A Lei do Direito de Voto', fato: 'Em 6 de agosto de 1965, a Voting Rights Act proibiu os testes de alfabetização e outras barreiras usadas para impedir o voto dos negros no Sul.', peso: 'biografia', idadeMin: 12, fonte: 'National Archives; U.S. Department of Justice.' },
    { id: 'medicare', data: [1965, 7], categoria: 'saude', titulo: 'O Medicare e o Medicaid', fato: 'Em julho de 1965 foram criados o Medicare (seguro de saúde público para quem tem 65 anos ou mais) e o Medicaid (para os mais pobres).', peso: 'cotidiano', idadeMin: 16, fonte: 'Centers for Medicare & Medicaid Services (History).' },
    { id: 'vietna', data: [1965, 3], categoria: 'guerra', titulo: 'As tropas de combate no Vietnã', fato: 'Em março de 1965, os primeiros fuzileiros de combate desembarcaram no Vietnã. A guerra e a convocação dividiram o país: protestos nos campi, cartões de convocação queimados, famílias rachadas.', peso: 'biografia', fonte: 'National Archives; Department of Veterans Affairs.' },
    { id: 'king', data: [1968, 4], categoria: 'politica', titulo: 'O assassinato de Martin Luther King Jr.', fato: 'Em 4 de abril de 1968, Martin Luther King Jr. foi assassinado em Memphis. Mais de cem cidades tiveram protestos nos dias seguintes; em junho, Robert Kennedy também foi morto.', peso: 'biografia', fonte: 'The King Center; National Archives.' },
    { id: 'apollo11', data: [1969, 7], categoria: 'tecnologia', titulo: 'O homem pisa na Lua', fato: 'Em 20 de julho de 1969, a Apollo 11 pousou na Lua; Neil Armstrong e Buzz Aldrin caminharam por ela diante de centenas de milhões de telespectadores.', peso: 'biografia', idadeMin: 4, fonte: 'NASA History Office.' },
    { id: 'roe', data: [1973, 1], categoria: 'direitos', titulo: 'O aborto legal em todo o país', fato: 'Em 22 de janeiro de 1973, a Suprema Corte (Roe v. Wade) reconheceu o direito ao aborto nos primeiros meses de gestação em todos os estados.', peso: 'cotidiano', idadeMin: 16, fonte: 'Supreme Court of the United States, 410 U.S. 113.' },
    { id: 'fim_convocacao', data: [1973, 7], categoria: 'politica', titulo: 'O fim da convocação militar', fato: 'Em 1973, a convocação obrigatória acabou: as Forças Armadas passaram a ser só de voluntários. O registro dos homens de 18 anos voltou em 1980, sem convocação.', peso: 'cotidiano', idadeMin: 14, fonte: 'Selective Service System (History and Records).' },
    { id: 'petroleo_73', data: [1973, 10], categoria: 'economia', titulo: 'A crise do petróleo', fato: 'Em outubro de 1973, o embargo dos países árabes quadruplicou o preço do petróleo: filas nos postos, gasolina racionada por placa e uma década de inflação alta.', peso: 'cotidiano', mods: { clientela: -4, reajuste: -0.01 }, dura: 1, fonte: 'U.S. Department of State, Office of the Historian ("Oil Embargo, 1973–1974").' },
    { id: 'watergate', data: [1974, 8], categoria: 'politica', titulo: 'A renúncia de Nixon', fato: 'Em 9 de agosto de 1974, Richard Nixon renunciou por causa do escândalo de Watergate — o único presidente americano a renunciar.', peso: 'cotidiano', idadeMin: 10, fonte: 'Richard Nixon Presidential Library; National Archives.' },
    { id: 'recessao_82', data: [1982, 11], categoria: 'economia', titulo: 'O desemprego de 1982', fato: 'Com os juros altíssimos usados para derrubar a inflação, o desemprego passou de 10% no fim de 1982 — o maior desde a Depressão. As cidades industriais do Meio-Oeste nunca mais foram as mesmas.', peso: 'cotidiano', mods: { demissao: 1.3, contratacao: -0.06 }, fonte: 'Bureau of Labor Statistics; Federal Reserve History ("Recession of 1981–82").' },
    { id: 'challenger', data: [1986, 1], categoria: 'desastre', titulo: 'A explosão da Challenger', fato: 'Em 28 de janeiro de 1986, o ônibus espacial Challenger explodiu 73 segundos depois de decolar, com sete tripulantes — entre eles uma professora. Muitas escolas assistiam ao vivo.', peso: 'cotidiano', idadeMin: 5, fonte: 'NASA History Office.' },
    { id: 'ada', data: [1990, 7], categoria: 'direitos', titulo: 'A lei dos americanos com deficiência', fato: 'Em julho de 1990, a Americans with Disabilities Act proibiu a discriminação de pessoas com deficiência no trabalho, no transporte e nos lugares públicos.', peso: 'cotidiano', idadeMin: 14, fonte: 'U.S. Department of Justice (ADA.gov).' },
    { id: 'golfo', data: [1991, 1], categoria: 'guerra', titulo: 'A Guerra do Golfo', fato: 'Em janeiro de 1991, uma coalizão liderada pelos Estados Unidos atacou o Iraque para tirá-lo do Kuwait; a guerra foi a primeira transmitida ao vivo pela televisão a cabo.', peso: 'cotidiano', fonte: 'Department of Defense; National Archives.' },
    { id: 'la_1992', data: [1992, 4], categoria: 'sociedade', titulo: 'Os protestos de Los Angeles', fato: 'Em abril de 1992, a absolvição dos policiais filmados espancando Rodney King levou a seis dias de protestos e incêndios em Los Angeles; mais de 60 pessoas morreram.', divisoes: ['CA'], peso: 'biografia', fonte: 'Los Angeles Public Library; California State Archives.' },
    { id: 'copa_94', data: [1994, 6], categoria: 'esporte', titulo: 'A Copa do Mundo nos Estados Unidos', fato: 'Em junho e julho de 1994, a Copa do Mundo foi disputada em nove cidades americanas, com estádios cheios; dois anos depois nasceu a liga profissional de futebol do país.', peso: 'cotidiano', fonte: 'FIFA; U.S. Soccer.' },
    { id: 'onze_setembro', data: [2001, 9], categoria: 'desastre', titulo: 'Os ataques de 11 de setembro', fato: 'Em 11 de setembro de 2001, aviões sequestrados atingiram as torres do World Trade Center, em Nova York, e o Pentágono; quase 3 mil pessoas morreram. Os aeroportos, as viagens e a política mudaram por anos.', peso: 'biografia', pessoal: { trabalho: 'No trabalho, as pessoas pararam diante das televisões.' }, fonte: 'National Commission on Terrorist Attacks (9/11 Commission Report); 9/11 Memorial & Museum.' },
    { id: 'iraque', data: [2003, 3], categoria: 'guerra', titulo: 'A invasão do Iraque', fato: 'Em março de 2003, os Estados Unidos invadiram o Iraque; a guerra e a do Afeganistão (desde 2001) levaram milhões de militares voluntários a missões repetidas.', peso: 'cotidiano', fonte: 'Department of Defense; Congressional Research Service.' },
    { id: 'katrina', data: [2005, 8], categoria: 'desastre', titulo: 'O furacão Katrina', fato: 'Em agosto de 2005, o furacão Katrina rompeu os diques de Nova Orleans; mais de 1.800 pessoas morreram e a resposta lenta do governo virou escândalo nacional.', peso: 'cotidiano', fonte: 'National Hurricane Center (NOAA); FEMA.' },
    { id: 'crise_2008', data: [2008, 9], categoria: 'economia', titulo: 'A crise financeira de 2008', fato: 'Em 15 de setembro de 2008, o banco Lehman Brothers quebrou. Veio a pior crise desde a Depressão: milhões perderam o emprego e a casa hipotecada.', peso: 'biografia', mods: { demissao: 1.4, contratacao: -0.08, clientela: -6 }, dura: 1, efeito: 'Nos meses seguintes, as empresas cortaram e quase ninguém contratou.', fonte: 'Federal Reserve History ("The Great Recession and Its Aftermath"); Bureau of Labor Statistics.' },
    { id: 'obama', data: [2009, 1], categoria: 'politica', titulo: 'O primeiro presidente negro', fato: 'Em 20 de janeiro de 2009, Barack Obama tomou posse — o primeiro presidente negro dos Estados Unidos.', peso: 'cotidiano', fonte: 'National Archives; Biblioteca do Congresso.' },
    { id: 'aca', data: [2010, 3], categoria: 'saude', titulo: 'A reforma da saúde', fato: 'Em março de 2010, a Affordable Care Act ampliou o seguro de saúde: proibiu negar cobertura por doença anterior e subsidiou planos para quem não tinha.', peso: 'cotidiano', idadeMin: 16, fonte: 'U.S. Department of Health and Human Services (HealthCare.gov).' },
    { id: 'obergefell', data: [2015, 6], categoria: 'direitos', titulo: 'O casamento igualitário em todo o país', fato: 'Em 26 de junho de 2015, a Suprema Corte (Obergefell v. Hodges) garantiu o casamento entre pessoas do mesmo sexo em todos os estados.', peso: 'cotidiano', idadeMin: 12, fonte: 'Supreme Court of the United States, 576 U.S. 644.' },
    { id: 'covid_us', data: [2020, 3], categoria: 'saude', titulo: 'A pandemia de covid-19', fato: 'Em março de 2020, a covid-19 fechou escolas, escritórios e comércio em todo o país; mais de um milhão de americanos morreram nos três anos seguintes.', peso: 'biografia', idadeMin: 4, mods: { demissao: 1.5, contratacao: -0.1, clientela: -8 }, efeito: 'O desemprego saltou para quase 15% em abril de 2020.', fonte: 'CDC; Bureau of Labor Statistics.' },
    { id: 'capitolio', data: [2021, 1], categoria: 'politica', titulo: 'A invasão do Capitólio', fato: 'Em 6 de janeiro de 2021, apoiadores do presidente derrotado invadiram o Capitólio durante a contagem dos votos do Colégio Eleitoral.', peso: 'cotidiano', idadeMin: 12, fonte: 'U.S. House Select Committee to Investigate the January 6th Attack (relatório final, 2022).' },
    { id: 'dobbs', data: [2022, 6], categoria: 'direitos', titulo: 'A Suprema Corte derruba Roe v. Wade', fato: 'Em 24 de junho de 2022, a Suprema Corte (Dobbs v. Jackson) devolveu aos estados a decisão sobre o aborto; vários estados o proibiram em seguida.', peso: 'cotidiano', idadeMin: 14, fonte: 'Supreme Court of the United States, 597 U.S. 215.' },
    { id: 'olimpiada_32', data: [1932, 7], categoria: 'esporte', titulo: 'Os Jogos Olímpicos de Los Angeles', fato: 'Em julho de 1932, em plena Depressão, Los Angeles recebeu os Jogos Olímpicos; foi a primeira vez que uma vila olímpica hospedou os atletas.', divisoes: ['CA'], peso: 'cotidiano', fonte: 'Comitê Olímpico Internacional.' },
    { id: 'olimpiada_84', data: [1984, 7], categoria: 'esporte', titulo: 'Os Jogos de Los Angeles', fato: 'Em julho de 1984, Los Angeles recebeu os Jogos Olímpicos, boicotados pela União Soviética e por seus aliados.', peso: 'cotidiano', fonte: 'Comitê Olímpico Internacional.' },
    { id: 'olimpiada_96', data: [1996, 7], categoria: 'esporte', titulo: 'Os Jogos de Atlanta', fato: 'Em julho de 1996, Atlanta recebeu os Jogos do centenário olímpico.', divisoes: ['GA'], peso: 'cotidiano', fonte: 'Comitê Olímpico Internacional.' }
